{
  "reading": "Asked: does V14 / jaws-v1 serve the restated plan (land Shabraz, grow him by draw, fly Humans, Treasure, wheel, kill by commander damage)? Draw (14) and wheels (10) are fully built; Treasure is one card (Smothering Tithe) and Humans-as-fliers is thin. The old ping plan survives in Torbran and the two red damage enchantments, and the deck's own goldfish_targets.json still declares the discard/damage-amplifier machine, so the goldfish's damage row measures the old plan.",
  "log_entries_read": ["007", "008", "009"],
  "axes_engaged": [
    {"axis": "colour-sources", "verdict": "weakness", "measured": {"value": "-11"}, "reading": "Worst colour 11 sources short; the RRR cards (Torbran, Gratuitous Violence, Fiery Emancipation) are what red is short for."},
    {"axis": "interaction", "verdict": "weakness", "measured": {"value": "6"}, "reading": "Under 8 on V14; jaws-v1 adds Voracious Greatshark and Kozilek's Return."},
    {"axis": "sweepers", "verdict": "weakness", "measured": {"value": "0"}, "reading": "None on V14; Kozilek's Return on the branch, which also kills the deck's 1-2 toughness Humans."},
    {"axis": "ramp", "verdict": "adequate", "measured": {"value": "13"}, "reading": "Over target; turn-5 Shabraz is not the binding problem (consistency 0.932)."}
  ],
  "cut_candidates": [
    {"card": "Fiery Emancipation", "why": "Six-mana RRR enchantment from the old red-amplifier plan; the pilot says the doublers/triplers are no longer the strategy.", "cost_of_cutting": "It does triple Shabraz's combat (commander) damage and Brallin's pings; losing it lowers the burst ceiling of an assembled double-strike Shabraz.", "difficulty": "easy", "orphans_stack": []},
    {"card": "Gratuitous Violence", "why": "Five-mana RRR enchantment competing with Shabraz for the turn-5 slot, filed with the old amplifiers.", "cost_of_cutting": "It doubles Shabraz's combat damage, so it is a real commander-damage multiplier; cutting it lengthens the 21-damage clock.", "difficulty": "contested", "orphans_stack": []}
  ],
  "add_candidates": [],
  "open_questions": [
    {"question": "Torbran is on protected.json but the pilot said 2026-11-25 'there is no keep list' and 'Torbran is weak in this deck now'. Does he want Kitsa/Torbran removed from protected.json?", "settled_by": "research-strategy", "why_it_matters": "The validator refuses any cut of Torbran until the hand-written keep list changes."},
    {"question": "goldfish_targets.json still declares the discard/damage-amplifier machine; should its targets be re-authored to the Shabraz commander-damage plan?", "settled_by": "goldfish", "why_it_matters": "Study 006's damage @T10 row (-42%) prices the old ping plan, not the stated one."}
  ],
  "gaps": ["Leitmotif Composer, named among his five Humans, is in neither list (watchlist only).", "No Treasure-maker scout run; adds go to the scout."]
}
